import{_ as t,a as s}from"./chunks/ugso_trigger_value.BNdSBQ-1.js";import{_ as r,a as n}from"./chunks/ugso_trigger_value.B1HIiOLA.js";import{_ as a,a as o}from"./chunks/schedule-dark-de.BuIYgk9x.js";import{_ as i,o as l,c as d,a3 as u}from"./chunks/framework.BlfGB29P.js";const c="/assets/blocks-for-ha/schedule-fr.png",p="/assets/blocks-for-ha/schedule-dark-fr.png",L=JSON.parse('{"title":"Date et heure","description":"","frontmatter":{"title":"Date et heure"},"headers":[],"relativePath":"fr/projects/blocks-for-ha/time.md","filePath":"fr/projects/blocks-for-ha/time.md","lastUpdated":1793126673000}'),m={name:"fr/projects/blocks-for-ha/time.md"};function h(g,e,b,f,v,k){return l(),d("div",null,[...e[0]||(e[0]=[u('<h1 id="date-et-heure" tabindex="-1">Date et heure <a class="header-anchor" href="#date-et-heure" aria-label="Permalink to &quot;Date et heure&quot;">​</a></h1><h2 id="horaires-et-declencheurs-depuis-0-1-60" tabindex="-1">Horaires et déclencheurs depuis 0.1.60 <a class="header-anchor" href="#horaires-et-declencheurs-depuis-0-1-60" aria-label="Permalink to &quot;Horaires et déclencheurs depuis 0.1.60&quot;">​</a></h2><p>Cliquer sur le champ CRON dans <strong>Déclencheurs → Horaire</strong>. Le dialogue propose <strong>Assistant / Simple / CRON</strong>, suivant les fenêtres ioBroker. Simple définit des intervalles ; Assistant propose aussi une heure précise avec des jours numériques. CRON dispose d’onglets par champ et de secondes facultatives. <strong>OK</strong> applique une règle valide ; <strong>Annuler</strong> et Échap conservent la valeur précédente. Thèmes clair/sombre et textes DE/EN/FR disponibles.</p><p><img src="'+t+'" alt="Horaire"></p><p><img src="'+c+'" alt="Dialogue CRON"></p><p><img src="'+p+'" alt="Dialogue CRON sombre"></p><p>Cinq champs : minute, heure, jour du mois, mois, jour de semaine. Six champs commencent par les secondes. Nombres, listes, plages et pas sont acceptés. Exemples : <code>*/5 * * * *</code> toutes les cinq minutes ; <code>*/30 * * * * *</code> toutes les 30 secondes ; <code>30 7 * * 1-5</code> du lundi au vendredi à 07:30. Dimanche : 0 ou 7. Home Assistant exécute dans son heure locale, sans minuterie du navigateur. Les pas suivent les champs de l’horloge : <code>*/7</code> minutes recommence à la minute 0 de chaque heure.</p><p>La sortie utilise <code>time_pattern</code> ou <code>time</code> avec <code>weekday</code>. Mois et jour du mois doivent être <code>*</code>. Dates, périodes de validité, exécution unique et plages astronomiques jour/nuit ne sont pas encore implémentés dans ce dialogue. Les règles non prises en charge sont explicitement refusées. Les règles par jours sont limitées à 2000 heures individuelles ; au-delà, elles sont refusées. Déclencheurs calendrier et conditions HA restent disponibles séparément. Le JSON du projet conserve la règle CRON ; le YAML conserve la structure HA native équivalente.</p><table tabindex="0"><thead><tr><th>Déclencheur ioBroker</th><th>Blocks for HA / équivalent HA</th></tr></thead><tbody><tr><td>Si objet / Si objets</td><td>Déclencheur d’état avec une ou plusieurs entités ; état précédent/suivant, attribut et durée. Pas d’identifiants d’objets ioBroker.</td></tr><tr><td>Déclenché par / confirmer la valeur</td><td>Pas d’équivalent ioBroker <code>ack</code> ici dans HA. Aucun bloc artificiel de confirmation.</td></tr><tr><td>↪ Valeur / Message</td><td>Nouveau bloc de données : état actuel/précédent, ID d’entité, ID/type du déclencheur, message MQTT/JSON et données d’événement. Donnée absente : <code>none</code> ; convertir les nombres si nécessaire.</td></tr><tr><td>Astro avec décalage</td><td>Lever/coucher du soleil avec décalage facultatif en minutes. Autres conditions solaires via les blocs HA natifs.</td></tr><tr><td>Horaire / CRON</td><td>Dialogue ci-dessus, exécution HA native. Pas d’enregistrement dynamique d’horaires ioBroker nommés.</td></tr><tr><td>Message reçu</td><td>Déclencheur MQTT ou événement HA avec filtre ; pas de réception directe de messages entre scripts ioBroker.</td></tr><tr><td>Message de journal</td><td>Événement HA <code>system_log_event</code>, si HA est configuré pour fournir ces événements. Aucun écouteur ioBroker dédié.</td></tr><tr><td>Événements de fichiers/enums</td><td>Pas d’équivalent direct. Utiliser une intégration HA disponible et ses événements/entités.</td></tr><tr><td>Autres déclencheurs HA natifs</td><td>MQTT, modèle, webhook, appareil, tag, conversation, zone et géolocalisation figurent directement dans <strong>Déclencheurs</strong>, sans doublons dans HA avancé.</td></tr></tbody></table><p><img src="'+s+'" alt="Données du déclencheur"></p><p>Références : <a href="https://github.com/ioBroker/ioBroker.javascript/blob/master/src-editor/src/Components/blockly-plugins/blocks/blocks_trigger.ts" target="_blank" rel="noreferrer">blocs ioBroker originaux</a>, <a href="https://www.home-assistant.io/docs/automation/trigger/" target="_blank" rel="noreferrer">déclencheurs HA natifs</a>. L’apparence suit l’original ; exécution et données restent propres à HA.</p><p>Les blocs utilisent l’heure locale et le fuseau de <strong>Home Assistant</strong>, pas l’horloge du navigateur. Une date calculée reste un objet date Jinja ; convertir explicitement avant de l’afficher ou de la sérialiser en JSON. <a href="./blocks">Images et fonctions</a>.</p><table tabindex="0"><thead><tr><th>Fonction</th><th>Comportement</th></tr></thead><tbody><tr><td>Comparaison de l’heure actuelle</td><td>Avant, avant ou égal, après, après ou égal, égal, entre ou hors de. Format <code>HH:mm</code> ou <code>HH:mm:ss</code>.</td></tr><tr><td>Comparaison avec entrée</td><td>Heure sous forme de texte raccordé. Décocher l’heure actuelle fait apparaître une entrée de date à comparer.</td></tr><tr><td>Entre deux heures</td><td>Début inclus, fin exclue, y compris à travers minuit. Bornes égales : plage vide.</td></tr><tr><td>Date actuelle</td><td><code>now()</code> de HA, avec fuseau, pour calculer ou formater.</td></tr><tr><td>Date calculée</td><td>Début du jour, du jour suivant, de la semaine (lundi), du mois ou de l’année.</td></tr><tr><td>Événement solaire</td><td>Prochain lever, coucher, aube, crépuscule, midi ou minuit solaire dans <code>sun.sun</code>. Décalage en minutes ; événement éventuellement demain.</td></tr><tr><td>Décaler une date</td><td>Ajouter/soustraire millisecondes, secondes, minutes, heures ou jours. Nombre fini requis.</td></tr><tr><td>Formater</td><td>Texte d’heure/date, ISO avec fuseau ou secondes Unix.</td></tr><tr><td>Date du jour</td><td>Comparer une date de calendrier complète, année incluse, avec le calendrier de HA.</td></tr></tbody></table><p>Une comparaison est une <strong>condition</strong>, pas un déclencheur périodique. Pour démarrer à une heure ou un événement solaire, utiliser les déclencheurs correspondants. Une valeur solaire absente provoque une erreur de modèle ; elle n’est pas remplacée silencieusement.</p><p>Les frontières de calendrier et changements d’heure suivent les calculs de HA. Pour un intervalle de durée fixe, distinguer durée écoulée et changement de jour du calendrier. Les tests vérifient notamment les plages passant par minuit et les frontières de fuseau.</p><p>Les variantes ioBroker ont servi de référence fonctionnelle ; les expressions sont une implémentation UGSo pour HA/Jinja. Voir <a href="https://github.com/ioBroker/ioBroker.javascript" target="_blank" rel="noreferrer">source ioBroker</a> et <a href="https://www.home-assistant.io/docs/configuration/templating/" target="_blank" rel="noreferrer">modèles HA</a>.</p><details class="details custom-block"><summary>Référence détaillée issue de la documentation allemande</summary><h2 id="datum-und-zeit" tabindex="-1">Date et heure <a class="header-anchor" href="#datum-und-zeit" aria-label="Permalink to &quot;Date et heure {#datum-und-zeit}&quot;">​</a></h2><h3 id="zeitplan-und-ausloser-seit-0-1-60" tabindex="-1">Planification et déclencheurs (depuis 0.1.60) <a class="header-anchor" href="#zeitplan-und-ausloser-seit-0-1-60" aria-label="Permalink to &quot;Planification et déclencheurs (depuis 0.1.60) {#zeitplan-und-ausloser-seit-0-1-60}&quot;">​</a></h3><p>Dans la section <strong>Déclencheurs → Planification</strong>, cliquez sur la règle CRON. La boîte de dialogue propose les modes <strong>Assistant / Simple / CRON</strong>, calqués sur les fenêtres contextuelles d&#39;ioBroker. Le mode « Simple » permet de créer des intervalles ; le mode « Assistant » ajoute la possibilité de définir une heure fixe ainsi que des jours de la semaine (sous forme numérique). Le mode « CRON » dispose d&#39;onglets pour chaque champ et inclut, en option, la gestion des secondes. Le bouton <strong>OK</strong> valide la règle saisie, tandis que <strong>Annuler</strong> (ou la touche Échap) conserve la valeur précédente. L&#39;affichage s&#39;adapte au mode clair ou sombre. Tous les textes des boîtes de dialogue sont disponibles en allemand, anglais et français.</p><p><img src="'+r+'" alt="Calendrier"></p><p><img src="'+a+'" alt="Dialogue CRON"></p><p><img src="'+o+'" alt="Dialogue CRON (thème sombre)"></p><p>Cinq champs : minute, heure, jour du mois, mois, jour de la semaine. Les formats à six champs commencent par les secondes. Il est possible d&#39;utiliser des nombres, des listes, des plages et des pas (incréments). Exemples : <code>*/5 * * * *</code> toutes les cinq minutes ; <code>*/30 * * * * *</code> toutes les 30 secondes ; <code>30 7 * * 1-5</code> les jours ouvrables à 07h30. Le dimanche correspond à 0 ou 7. Home Assistant exécute l&#39;automatisation selon son heure locale ; il ne s&#39;agit pas d&#39;un minuteur basé sur le navigateur. <code>/Schritte</code> se rapporte au champ temporel concerné : <code>*/7</code> pour les minutes, le décompte repart à 0 à chaque nouvelle heure.</p><p>La sortie utilise des déclencheurs natifs <code>time_pattern</code> ou <code>time</code> avec <code>weekday</code>. Le mois et le jour du mois doivent être <code>*</code>. Les dates, les plages de validité, les événements ponctuels et les fenêtres astronomiques (jour/nuit) ne sont pas encore implémentés dans la boîte de dialogue. Ces règles ne sont pas ignorées silencieusement. Les règles basées sur les jours de la semaine sont résolues en un maximum de 2000 horaires individuels ; les règles générant une fréquence supérieure sont explicitement rejetées. Les déclencheurs basés sur le calendrier et les conditions Home Assistant restent disponibles séparément. Le fichier JSON du projet intègre la règle CRON, tandis que le fichier YAML contient la structure native équivalente de Home Assistant.</p><table tabindex="0"><thead><tr><th>Déclencheur ioBroker</th><th>Blocks for HA / Adaptation pour HA</th></tr></thead><tbody><tr><td>Si objet / Si objets</td><td>Déclencheur d&#39;état basé sur une ou plusieurs entités ; paramètres : de/vers, attribut et durée de maintien. Pas d&#39;identifiants d&#39;objets ioBroker.</td></tr><tr><td>Déclenché par / Confirmation (ack)</td><td>HA ne dispose pas de l&#39;équivalent du <code>ack</code> d&#39;ioBroker. Pas de bloc de confirmation artificiel.</td></tr><tr><td>↪ Valeur / Message</td><td>Nouveau bloc de données de déclenchement : valeur, ancienne valeur, ID d&#39;entité, ID/type de déclencheur, message MQTT/JSON et données d&#39;événement. Les données manquantes renvoient <code>none</code> ; conversion des nombres si nécessaire.</td></tr><tr><td>Astro avec décalage</td><td>Lever/coucher du soleil avec décalage optionnel en minutes. Autres conditions solaires gérées via les blocs natifs de HA.</td></tr><tr><td>Planification / CRON</td><td>Interface identique à celle décrite ci-dessus, exécution native dans HA. Pas d&#39;enregistrement dynamique de planifications nommées issues d&#39;ioBroker.</td></tr><tr><td>Réception de message</td><td>Déclencheur basé sur un événement MQTT ou HA avec filtre ; pas de réception directe de messages de scripts ioBroker.</td></tr><tr><td>Message de journal (Log)</td><td>Déclencheur d&#39;événement HA utilisant <code>system_log_event</code>, sous réserve que HA fournisse ces événements. Pas d&#39;écouteur de logs ioBroker dédié.</td></tr><tr><td>Événements de fichiers / Énumérations</td><td>Pas de transposition directe. Utiliser les intégrations HA existantes ou leurs événements/entités correspondants.</td></tr><tr><td>Autres déclencheurs natifs HA</td><td>Les déclencheurs MQTT, Template, Webhook, Appareil (Device), Tag, Conversation, Zone et Géolocalisation sont désormais disponibles directement sous <strong>Déclencheurs</strong>, sans doublon dans la section étendue HA.</td></tr></tbody></table><p><img src="'+n+'" alt="Données de déclenchement"></p><p>Références : <a href="https://github.com/ioBroker/ioBroker.javascript/blob/master/src-editor/src/Components/blockly-plugins/blocks/blocks_trigger.ts" target="_blank" rel="noreferrer">Blocs déclencheurs originaux d&#39;ioBroker</a>, <a href="https://www.home-assistant.io/docs/automation/trigger/" target="_blank" rel="noreferrer">déclencheurs natifs de HA</a>. L&#39;interface s&#39;inspire de l&#39;original ; l&#39;exécution et les données restent spécifiques à HA.</p><p>Depuis <strong>0.1.11</strong>, la catégorie contient sept blocs supplémentaires. <a href="/fr/projects/blocks-for-ha/blocks#datum-und-zeit-seit-0-1-11">Tous les blocs avec illustrations</a>. L&#39;interface utilise la bibliothèque Blockly originale ; la traduction vers Jinja (pour HA) est une implémentation propre à UGSo. Les références sont les <a href="https://github.com/ioBroker/ioBroker.javascript/blob/master/src-editor/src/Components/blockly-plugins/blocks/blocks_time.ts" target="_blank" rel="noreferrer">blocs temporels de l&#39;adaptateur JavaScript d&#39;ioBroker</a> ainsi que les <a href="https://docs.blockly.com/guides/create-custom-blocks/define/block-definitions/" target="_blank" rel="noreferrer">définitions des blocs Blockly</a>.</p><h3 id="iobroker-ugso-blocks-fur-ha" tabindex="-1">Blocs ioBroker / UGSo pour HA <a class="header-anchor" href="#iobroker-ugso-blocks-fur-ha" aria-label="Permalink to &quot;Blocs ioBroker / UGSo pour HA {#iobroker-ugso-blocks-fur-ha}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ioBroker</th><th>Notre bloc / Implémentation</th></tr></thead><tbody><tr><td>Heure actuelle, heure fixe</td><td><strong>Comparaison horaire</strong> : inférieur à, inférieur ou égal à, supérieur à, supérieur ou égal à, égal à, compris entre et non compris entre. Le champ de fin apparaît lorsqu&#39;il s&#39;agit d&#39;une plage temporelle.</td></tr><tr><td>Heure actuelle avec case à cocher et entrée connectable</td><td><strong>Comparaison horaire avec entrées</strong> : blocs texte pour le début et la fin. Si la case est décochée, une entrée supplémentaire pour une valeur de date/heure à comparer devient disponible.</td></tr><tr><td>Heure actuelle sous forme d&#39;objet date ou de valeur formatée</td><td><strong>Heure actuelle en tant que valeur de date</strong> et <strong>bloc de formatage</strong> séparé. Cette distinction évite que des textes formatés ne soient interprétés par erreur comme des valeurs de date.</td></tr><tr><td>Temps calculé</td><td><strong>Début de période calendaire</strong> : jour, jour suivant, semaine (lundi), mois et année. D&#39;autres limites calendaires ioBroker ne sont pas encore disponibles.</td></tr><tr><td>Heure actuelle basée sur un événement astronomique avec décalage (offset)</td><td><strong>Événement solaire</strong> : lever, coucher, aube/crépuscule, zénith et minuit solaire, avec un décalage en minutes (positif ou négatif).</td></tr><tr><td>Calcul temporel : base ± nombre, unité</td><td><strong>Calcul temporel</strong> : valeur de date ± nombre ; en millisecondes, secondes, minutes, heures ou jours.</td></tr></tbody></table><h3 id="anschlusse-und-bedienung" tabindex="-1">Connexions et utilisation <a class="header-anchor" href="#anschlusse-und-bedienung" aria-label="Permalink to &quot;Connexions et utilisation {#anschlusse-und-bedienung}&quot;">​</a></h3><p>Les comparaisons temporelles renvoient une valeur <strong>booléenne</strong> et s&#39;intègrent dans des conditions (ET/OU/NON) ou des structures « si ». Les valeurs de date disposent d&#39;un <strong>connecteur temporel</strong> : l&#39;heure actuelle, le début de période calendaire, les événements solaires et les calculs temporels peuvent être imbriqués les uns dans les autres. Les nombres s&#39;insèrent dans les champs de décalage (offset) ou de valeur ; les heures formatées (sous forme de texte) s&#39;insèrent dans les limites de comparaison connectables. Le formatage propose : HH:mm, HH:mm:ss, date ISO, date au format allemand, date/heure, format ISO avec fuseau horaire et secondes Unix.</p><p>Exemple : <strong>Heure actuelle → Calculer l&#39;heure (+ 30 minutes) → Formater l&#39;heure (HH:mm)</strong>, puis définir le résultat en tant que variable. Le modèle (template) généré est le suivant :</p><div class="language-jinja vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">jinja</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">{{ (</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">now</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> timedelta</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">(</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">minutes</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">30)).</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">strftime</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;%H:%M&quot;</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">) }}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>Entre 22:00 et 06:00</strong> : cette plage couvre la nuit et inclut le passage à minuit. L&#39;heure de début est incluse, mais pas l&#39;heure de fin. Si les bornes sont identiques, la période est considérée comme vide ; « pas entre » correspond à l&#39;inverse. Les heures fixes doivent être au format HH:mm ou HH:mm:ss. Les bornes dynamiques doivent fournir le même format lors de l&#39;exécution ; des valeurs non valides entraîneront une erreur dans le modèle HA (Home Assistant). La comparaison s&#39;effectue à la seconde près ; ainsi, « égal à 12:00 » équivaut à 12:00:00 et ne constitue pas un déclencheur temporel fiable.</p><h3 id="ausfuhrung-und-grenzen" tabindex="-1">Exécution et limites <a class="header-anchor" href="#ausfuhrung-und-grenzen" aria-label="Permalink to &quot;Exécution et limites {#ausfuhrung-und-grenzen}&quot;">​</a></h3><p>Les modèles (templates) générés sont évalués <strong>dans Home Assistant</strong>. Le navigateur construit le code YAML mais n&#39;exécute pas de gestion temporelle propre. Les fonctions utilisent le fuseau horaire configuré dans HA : <a href="https://www.home-assistant.io/template-functions/#date-time" target="_blank" rel="noreferrer">Fonctions de date/heure HA</a>. Le début d&#39;une journée calendaire se base sur minuit heure locale ; les jours suivent le calendrier local, y compris lors des changements d&#39;heure (passage à l&#39;heure d&#39;été/hiver). Un calcul de type « + 24 heures » ne garantit pas, lors d&#39;un changement d&#39;heure, l&#39;écoulement de 24 heures réelles en temps universel (UTC).</p><p>Les données solaires proviennent des attributs de l&#39;<strong>intégration « Sun » (Soleil) de HA</strong> (<a href="https://www.home-assistant.io/integrations/sun/#sensors" target="_blank" rel="noreferrer">HA-Sun-Integration</a>). Celles-ci fournissent l&#39;<strong>événement suivant</strong>, et non systématiquement l&#39;événement du jour en cours. La valeur en UTC est convertie en heure locale HA avant tout calcul ou formatage. L&#39;absence de valeur — par exemple si l&#39;intégration est indisponible ou si un événement ne peut être calculé — entraîne une erreur dans le modèle ; aucune heure de remplacement n&#39;est générée automatiquement.</p><p>Une comparaison temporelle vérifie l&#39;heure <strong>au moment de l&#39;évaluation de la condition</strong>. Elle ne déclenche pas l&#39;automatisation et n&#39;attend pas que l&#39;heure correspondante soit atteinte. Pour cela, il convient d&#39;utiliser un déclencheur basé sur l&#39;heure ou sur le soleil. Le nouveau bloc de données solaires ne remplace pas un déclencheur solaire.</p><p>Le projet « Blocks » (au format JSON) intègre des formulaires, des sélections et des entrées dynamiques. Lors de l&#39;<strong>ouverture en mode YAML</strong>, le contenu de ces modèles temporels est préservé, mais ils apparaissent sous forme de blocs de modèles génériques. Une valeur de date préalablement stockée dans une variable HA peut être traitée comme du texte ; c&#39;est pourquoi notre bloc de lecture de variables ne dispose pas de connecteur de type « heure » (Time). Imbriquez directement les valeurs de date ou, depuis la version <strong>0.1.12</strong>, convertissez le bloc de lecture de variables via l&#39;option <strong>Par date/heure</strong>. <a href="/fr/projects/blocks-for-ha/conversion">Conversion et unités</a>. Les valeurs temporelles converties peuvent désormais être utilisées pour définir des montants ou des décalages par rapport au soleil (offset solaire).</p><p>Vérification : allers-retours Blockly/YAML, connexions typées, champs dynamiques ainsi que contrôles Jinja pour les limites nocturnes et l&#39;heure d&#39;été. L&#39;exécution sur un système HA (Home Assistant) réel n&#39;a pas encore été vérifiée.</p></details>',17)])])}const _=i(m,[["render",h]]);export{L as __pageData,_ as default};
